  ('2c694d19-5d91-4c37-8719-da73807fafc2', 'IB_ECONOMICS', 'SL', 'IB_ECON_001', 'P1', 'P1_part_a', 'explain', 10, 'AO2', NULL, 'Explain why economics is considered a social science and how the use of models and assumptions helps economists study real-world economic behaviour.', NULL, NULL, NULL, NULL, NULL, 'seed', 'claude_draft', 'f70bc413-64ca-44f4-a5e2-a970f60c53a5', '2026-05-22T15:55:20.081+00:00', 'gradd_original', 'V2', 'pass'),
