  ('cb4f6782-2122-4e41-8bfa-d25777a68d7f', 'IB_ECONOMICS', 'SL', 'IB_ECON_039', 'P2', 'P2_part_a', 'calculate', 2, 'AO4', NULL, 'Calculate the price elasticity of demand (PED) for fresh strawberries.', 'When the price of fresh strawberries rises from $2.00 to $2.50 per punnet, the quantity demanded falls from 8,000 punnets to 6,400 punnets per week in a local market.', NULL, NULL, NULL, NULL, 'seed', 'claude_draft', 'f70bc413-64ca-44f4-a5e2-a970f60c53a5', '2026-05-22T17:14:32.196+00:00', 'gradd_original', 'V2', 'pass'),
